const snoise=`fn mod289_v3(x:vec3f)->vec3f{return x-floor(x*(1.0 / 289.0))*289.0;}fn mod289_v2(x:vec2f)->vec2f{return x-floor(x*(1.0 / 289.0))*289.0;}fn permute(x:vec3f)->vec3f{return mod289_v3(((x*34.0)+10.0)*x);}fn snoise(v:vec2f)->f32{let C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);var i=floor(v+dot(v,C.yy));var x0=v-i+dot(i,C.xx);var i1=vec2(0.);if(x0.x > x0.y){i1=vec2(1.0,0.0);}else{i1=vec2(0.0,1.0);}var x12=x0.xyxy+C.xxzz;x12=vec4(x12.xy-i1,x12.zw);i=mod289_v2(i);let p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));var m=max(vec3(0.5)-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),vec3(0.0));m=m*m;m=m*m;let x=2.0*fract(p*C.www)-1.0;let h=abs(x)-0.5;let ox=floor(x+0.5);let a0=x-ox;m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);var g=vec3(0.);g.x=a0.x*x0.x+h.x*x0.y;g=vec3(g.x,a0.yz*x12.xz+h.yz*x12.yw);return 130.0*dot(m,g);}`;export{snoise};
